CREATE TABLE IF NOT EXISTS gis_canonical_source_identity (source_key text PRIMARY KEY, source_registry_id uuid NOT NULL, source_url text NOT NULL, authority_level text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO gis_canonical_source_identity(source_key,source_registry_id,source_url,authority_level) SELECT source_key,id,source_url,authority_level FROM gis_official_source_registry WHERE source_key='INEC-POLLING-UNIT-LOCATOR-2026' ON CONFLICT(source_key) DO UPDATE SET source_registry_id=EXCLUDED.source_registry_id,source_url=EXCLUDED.source_url,authority_level=EXCLUDED.authority_level,updated_at=now();